    "seat": "长安",
    "summary": "漢初、郡国制を併用し、匈奴と和親を結んだ。武帝は北方の匈奴を撃退し、河西回廊とシルクロードを開き、南方の南越を平定し、東方に朝鮮四郡を設置した。宣帝の時代には西域都護府が設置された。西暦8年、王莽が漢に代わり新を建国し、西暦23年には新は滅亡した。",
