    "summary": "420年、劉裕が晋に代わって宋を建国し、南朝は宋・斉・梁・陳と続いた。北方では北魏の太武帝拓跋燾が相次いで胡夏（431年）、北燕（436年）、北涼（439年）を滅ぼし、439年に正式に北方を統一して五胡十六国時代を終焉させた。534年、北魏は東魏と西魏に分裂し、それぞれ北斉、北周に取って代わられた。",
