    "summary": "盛唐期には、安西、北庭、安北、安東、安南などの都護府が設置され、長安は当時世界最大の都市であった。690年から705年にかけて、武則天が唐を周（武周）に改め、神都洛陽を都とした。755年の安史の乱後、河西、隴右、西域が相次いで吐蕃の支配下に入り、藩鎮が割拠し、907年に朱温が唐に代わるまで続いた。",
