    "seat": "京师（北京）",
    "summary": "1644年の入関後、康熙帝、雍正帝、乾隆帝の三朝を経て次第に版図を確立した。台湾を領有し、漠北、青海を平定、駐蔵大臣を設置し、天山山脈の南北を平定した。1840年以降は列強の度重なる侵略を受け、外東北とイリ西境を割譲した。",
